 @Test public void authoringToolsPreserveSourceAndStageReviewedNativeChanges()throws Exception{
  String source="{\"shortId\":\"fixed\",\"initialGameState\":{\"npcs\":{\"m\":{\"name\":\"M\",\"exact\":9007199254740993}}}}";
  String id=host.store.create("Native authoring audit",source).getJSONObject("project").getString("id");
  String hash=host.store.core.hash(source);JSONArray path=new JSONArray().put("initialGameState").put("npcs").put("m");
  host.request("featureSet",new JSONObject().put("key","readiness:"+id).put("value","{\"stage\":\"publish\"}"));assertTrue(((String)host.request("featureGet",new JSONObject().put("key","readiness:"+id))).contains("publish"));
  assertEquals("http://127.0.0.1:1234",host.store.core.doc("validateEndpoint","http://127.0.0.1:1234"));try{host.store.core.doc("validateEndpoint","http://remote.example/v1");fail("Remote plaintext endpoint allowed");}catch(Exception expected){assertTrue(expected.getMessage().contains("HTTPS"));}
  host.store.dispatch(id,new JSONObject().put("type","bookmark").put("id","bookmark").put("path",path).put("name","M").put("baseHash",hash));
  host.store.dispatch(id,new JSONObject().put("type","authoringProposal").put("operation","duplicate").put("id","copy").put("path",path).put("newKey","copy").put("baseHash",hash));
  assertEquals(source,host.store.project(id).getString("activeSource"));host.store.dispatch(id,new JSONObject().put("type","accept").put("id","copy"));
  JSONObject checkpoint=host.store.history(id).getJSONObject(0);JSONObject detail=(JSONObject)host.request("checkpointDetail",new JSONObject().put("id",id).put("checkpointId",checkpoint.getString("id")));assertEquals(source,detail.getString("source"));
  host.request("renameCheckpoint",new JSONObject().put("id",id).put("checkpointId",checkpoint.getString("id")).put("label","Before duplicate"));assertEquals("Before duplicate",host.store.history(id).getJSONObject(0).getString("label"));
  String copied=host.store.project(id).getString("activeSource");assertTrue(copied.contains("9007199254740993"));assertEquals(1,host.store.project(id).getJSONArray("bookmarks").length());
  JSONArray paths=new JSONArray().put(path).put(new JSONArray().put("initialGameState").put("npcs").put("copy"));
  host.store.dispatch(id,new JSONObject().put("type","authoringProposal").put("operation","batch").put("id","batch").put("paths",paths).put("field","name").put("source","\"Updated\"").put("baseHash",host.store.core.hash(copied)));
  assertEquals(copied,host.store.project(id).getString("activeSource"));host.store.dispatch(id,new JSONObject().put("type","accept").put("id","batch"));assertTrue(host.store.project(id).getString("activeSource").contains("9007199254740993"));
  JSONObject catalogue=(JSONObject)host.store.core.doc("entryCatalog",source,"M",0,20);assertTrue(catalogue.getInt("total")>0);
  JSONObject assets=(JSONObject)host.store.core.doc("assetInventory","{\"image\":\"data:image/png;base64,YQ==\"}","all",0,20);assertEquals(1,assets.getJSONArray("assets").getJSONObject(0).getInt("bytes"));
  String other=host.store.create("Other","{}").getJSONObject("project").getString("id");try{host.request("checkpointDetail",new JSONObject().put("id",other).put("checkpointId",checkpoint.getString("id")));fail("Cross-project checkpoint read allowed");}catch(Exception expected){assertTrue(expected.getMessage().contains("not found"));}
 }
 @Test public void flaggedNotesQueueUsesNativePlannerToolsWithoutWorldEdits()throws Exception{
  String source="{\"initialGameState\":{\"combatSettings\":{\"exact\":9007199254740993}}}";
  String id=host.store.create("Native note queue",source).getJSONObject("project").getString("id");
  Object hash=host.store.core.call(new JSONObject().put("operation","hash").put("source",source));
  JSONArray path=new JSONArray().put("initialGameState").put("combatSettings");
  host.store.dispatch(id,new JSONObject().put("type","builderNote").put("baseHash",hash).put("note",new JSONObject().put("id","note").put("path",path).put("text","Deepen combat with fatigue").put("planning",true)));
  host.store.dispatch(id,new JSONObject().put("type","prepareTask").put("id","plan").put("attempt","attempt").put("kind","plan").put("addressNotes",true));
  host.store.dispatch(id,new JSONObject().put("type","taskRunning").put("taskId","plan").put("attempt","attempt"));
  AgentService agent=new AgentService();agent.store=host.store;agent.projectId=id;agent.taskId="plan";agent.attempt="attempt";
  JSONObject notes=(JSONObject)agent.tool("world_notes",new JSONObject().put("path",path));assertEquals(1,notes.getJSONArray("notes").length());
  JSONObject order=new JSONObject().put("objective","Add fatigue").put("requirements",new JSONArray().put("Preserve exact numbers")).put("allowedPaths",new JSONArray().put(path));
  JSONObject suggestion=(JSONObject)agent.tool("propose_work_order",order);
  agent.tool("record_note_plan",new JSONObject().put("noteId","note").put("state","proposed").put("explanation","Scoped proposal ready").put("proposalId",suggestion.getString("proposalId")));
  host.store.dispatch(id,new JSONObject().put("type","taskDone").put("taskId","plan").put("attempt","attempt").put("text","Review the fatigue proposal"));
  JSONObject saved=host.store.project(id);assertEquals(source,saved.getString("activeSource"));assertEquals("",saved.getJSONObject("workOrder").getString("objective"));assertTrue(saved.getJSONArray("builderNotes").getJSONObject(0).getBoolean("planning"));
  JSONObject task=saved.getJSONArray("tasks").getJSONObject(0);assertTrue(task.getString("prompt").contains("BEGIN BUILDER NOTE QUEUE"));assertEquals("proposed",task.getJSONArray("noteQueue").getJSONObject(0).getString("state"));
  String suggestionId=suggestion.getString("proposalId");host.store.dispatch(id,new JSONObject().put("type","workOrder").put("order",new JSONObject(order.toString()).put("sourceProposalId",suggestionId)));
  host.store.dispatch(id,new JSONObject().put("type","prepareTask").put("id","work").put("attempt","work-attempt").put("kind","work"));
  host.store.dispatch(id,new JSONObject().put("type","taskRunning").put("taskId","work").put("attempt","work-attempt"));
  host.store.dispatch(id,new JSONObject().put("type","taskEdit").put("taskId","work").put("attempt","work-attempt").put("action","insert").put("path",path).put("key","fatigue").put("source","true"));
  host.store.dispatch(id,new JSONObject().put("type","taskDone").put("taskId","work").put("attempt","work-attempt"));
  assertEquals(source,host.store.project(id).getString("activeSource"));host.store.dispatch(id,new JSONObject().put("type","accept").put("id","work"));
  JSONObject detail=(JSONObject)host.request("noteChangeDetail",new JSONObject().put("id",id).put("receiptId","work"));assertEquals(source,detail.getString("before"));assertTrue(new JSONObject(detail.getString("after")).getJSONObject("initialGameState").getJSONObject("combatSettings").getBoolean("fatigue"));assertTrue(detail.getString("after").contains("9007199254740993"));assertEquals(2,host.store.history(id).length());

 }

 @Test public void planningProposesStructuredOrderWithoutApproval()throws Exception{
  String source="{\"initialGameState\":{\"npcs\":{\"mara\":{\"name\":\"Mara\"}}}}";
  String id=host.store.create("Structured planner test",source).getJSONObject("project").getString("id");
  host.store.dispatch(id,new JSONObject().put("type","prepareTask").put("id","plan").put("attempt","attempt").put("kind","plan").put("prompt","Improve Mara"));
  host.store.dispatch(id,new JSONObject().put("type","taskRunning").put("taskId","plan").put("attempt","attempt"));
  JSONObject order=new JSONObject().put("objective","Improve Mara").put("requirements",new JSONArray().put("Preserve identity")).put("allowedPaths",new JSONArray().put(new JSONArray().put("initialGameState").put("npcs").put("mara")));
  JSONObject command=new JSONObject().put("type","proposeWorkOrder").put("taskId","plan").put("attempt","attempt").put("id","suggestion").put("order",order);
  host.store.dispatch(id,command);
  JSONObject saved=host.store.project(id);assertEquals(source,saved.getString("activeSource"));assertEquals("",saved.getJSONObject("workOrder").getString("objective"));assertEquals(1,saved.getJSONArray("workOrderProposals").length());
  host.store.dispatch(id,new JSONObject().put("type","taskStop").put("taskId","plan"));
  try{host.store.dispatch(id,command.put("id","late"));fail("Stopped planner cannot propose");}catch(Exception expected){assertTrue(expected.getMessage().contains("planning attempt"));}
  String tools=new String(app.getAssets().open("tools-plan.json").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);assertTrue(tools.contains("propose_work_order"));assertFalse(tools.contains("world_edit"));
 }

 Context app;Host host;@Before public void setup()throws Exception{app=InstrumentationRegistry.getInstrumentation().getTargetContext();host=new Host(app);}
 @Test public void voyageProposalMustBeReviewedBeforeRemoteSave()throws Exception{String previous=host.store.setting("voyageEnvironment");try{host.store.setting("voyageEnvironment","alpha");String source="{\"title\":\"Local source\",\"initialGameState\":{}}";String id=host.store.create("Remote proposal guard",source).getJSONObject("project").getString("id");host.store.dispatch(id,new JSONObject().put("type","remoteLink").put("environment","alpha").put("worldId","test-world").put("etag","v1"));host.store.dispatch(id,new JSONObject().put("type","stage").put("id","remote-proposal").put("kind","remote").put("source","{\"title\":\"Remote source\",\"initialGameState\":{}}"));try{host.request("saveRemote",new JSONObject().put("id",id));fail("Unreviewed import cannot upload");}catch(Exception expected){assertTrue(expected.getMessage().contains("imported Voyage proposal"));}assertEquals(source,host.store.project(id).getString("activeSource"));assertEquals(0,host.store.project(id).getJSONObject("remote").getJSONArray("operations").length());}finally{host.store.setting("voyageEnvironment",previous);}}
 @Test public void voyageEnvironmentsPersistAndGuardLinkedWorlds()throws Exception{String previous=host.store.setting("voyageEnvironment"),oldAlpha=host.secrets.get("voyage-alpha");try{try{Host.apiBase("production");fail("Production must be disabled");}catch(Exception expected){assertTrue(expected.getMessage().contains("disabled"));}host.store.setting("voyageEnvironment","production");assertEquals("alpha",host.environment());assertEquals("https://api-alpha.aidungeon.com/creator/v1",Host.apiBase("alpha"));try{Host.apiBase("beta");fail("Beta must not use a guessed endpoint");}catch(Exception expected){assertTrue(expected.getMessage().contains("not confirmed"));}host.request("setVoyageEnvironment",new JSONObject().put("environment","alpha"));host.request("connectVoyage",new JSONObject().put("key","alpha-test-key"));Host reopened=new Host(app);assertEquals("alpha",((JSONObject)reopened.request("connection",new JSONObject())).getString("environment"));assertEquals("alpha-test-key",reopened.secrets.get("voyage-alpha"));JSONObject project=host.store.create("Environment guard","{\"initialGameState\":{}}").getJSONObject("project");String id=project.getString("id");host.store.dispatch(id,new JSONObject().put("type","remoteLink").put("environment","production").put("worldId","legacy-world").put("etag","v1"));try{host.request("setVoyageEnvironment",new JSONObject().put("environment","production"));fail("Production must be disabled");}catch(Exception expected){assertTrue(expected.getMessage().contains("disabled"));}for(String method:new String[]{"validateRemote","saveRemote","reconcileSave"})try{host.request(method,new JSONObject().put("id",id));fail("Cross-environment request must be blocked");}catch(Exception expected){assertTrue(expected.getMessage().contains("linked to production"));}}finally{host.store.setting("voyageEnvironment",previous);host.secrets.set("voyage-alpha",oldAlpha);}}
 @Test public void creatorAccessErrorExplainsRecovery(){String message=Host.apiErrorMessage(403,"{\"error\":{\"code\":\"creator_api_access_required\"},\"requestId\":\"request-123\"}");assertTrue(message.contains("Studio → Settings → API keys"));assertTrue(message.contains("Local editing remains available"));assertTrue(message.contains("Request ID: request-123"));assertEquals("Voyage HTTP 503: Request rejected.",Host.apiErrorMessage(503,"<html>private details</html>"));}
 @Test public void providerProbesUseNativeProtocols()throws Exception{for(String protocol:new String[]{"openai","openai-responses","anthropic","gemini"}){JSONObject profile=new JSONObject().put("id","test").put("name","Test").put("protocol",protocol).put("baseUrl","https://example.com/v1").put("model","test-model");JSONObject request=(JSONObject)host.store.core.doc("providerProbe",profile,"private-key","");assertFalse(new JSONObject(request.getString("body")).has("tools"));assertFalse(request.getString("body").contains("private-key"));assertTrue(request.getString("body").contains("Connection test"));}}
 @Test public void exactSourceAndDraftRecovery()throws Exception{String source="{\"title\":\"old\",\"id\":9007199254740993,\"huge\":1E+999,\"negative\":-0}";JSONObject p=host.store.create("Native fidelity test",source).getJSONObject("project");String id=p.getString("id");host.store.dispatch(id,new JSONObject().put("type","draft").put("path",new JSONArray().put("title")).put("text","\"draft\"").put("baseHash",host.store.core.hash(source)));Store reopened=new Store(app);assertEquals("\"draft\"",reopened.project(id).getJSONObject("draft").getString("text"));reopened.dispatch(id,new JSONObject().put("type","applyDraft"));assertEquals(source.replace("old","draft"),reopened.project(id).getString("activeSource"));assertEquals(1,reopened.history(id).length());}
 @Test public void fixtureAndRecovery()throws Exception{long started=System.currentTimeMillis();String source=host.asset("living-continuity.json");JSONObject p=host.store.create("Native large fixture",source).getJSONObject("project");String id=p.getString("id");host.store.core.doc("validate",source,host.references());for(int n=0;n<4;n++)host.store.dispatch(id,new JSONObject().put("type","stage").put("id","large-"+n).put("source",source).put("title","Large proposal "+n));assertEquals(4,host.store.project(id).getJSONArray("candidates").length());host.store.dispatch(id,new JSONObject().put("type","prepareTask").put("kind","plan").put("id","task").put("attempt","attempt").put("prompt","test"));host.store.dispatch(id,new JSONObject().put("type","recover"));assertEquals("INTERRUPTED",host.store.project(id).getJSONArray("tasks").getJSONObject(0).getString("state"));assertEquals(source,host.store.project(id).getString("activeSource"));android.util.Log.i("VoyageTest","large fixture core/store/validation ms="+(System.currentTimeMillis()-started));}
 @Test public void proposalRequiresAcceptanceAndRejectsStale()throws Exception{String source="{\"title\":\"old\"}";String id=host.store.create("Native proposal test",source).getJSONObject("project").getString("id");host.store.dispatch(id,new JSONObject().put("type","stage").put("id","candidate").put("source","{\"title\":\"proposal\"}").put("title","Proposal"));assertEquals(source,host.store.project(id).getString("activeSource"));host.store.dispatch(id,new JSONObject().put("type","edit").put("path",new JSONArray().put("title")).put("source","\"changed\"").put("baseHash",host.store.core.hash(source)));try{host.store.dispatch(id,new JSONObject().put("type","accept").put("id","candidate"));fail("stale acceptance allowed");}catch(Exception expected){assertTrue(expected.getMessage().contains("changed"));}}
 @Test public void localProviderStagesProposal()throws Exception{for(String protocol:new String[]{"openai","openai-responses","anthropic","gemini"})assertProviderStagesProposal(protocol);}
 void assertProviderStagesProposal(String protocol)throws Exception{String original=host.store.setting("providers");java.net.ServerSocket server=new java.net.ServerSocket(0,4,java.net.InetAddress.getByName("127.0.0.1"));server.setSoTimeout(30000);java.util.concurrent.atomic.AtomicReference<Throwable> failure=new java.util.concurrent.atomic.AtomicReference<>();Thread responder=new Thread(()->{try{for(int turn=0;turn<2;turn++){try(java.net.Socket client=server.accept()){BufferedReader in=new BufferedReader(new InputStreamReader(client.getInputStream(),java.nio.charset.StandardCharsets.UTF_8));int length=0;String line;while((line=in.readLine())!=null&&!line.isEmpty())if(line.toLowerCase().startsWith("content-length:"))length=Integer.parseInt(line.substring(15).trim());char[] chars=new char[length];int read=0;while(read<length){int n=in.read(chars,read,length-read);if(n<0)throw new IOException("Truncated request");read+=n;}JSONObject body=new JSONObject(new String(chars));if(!"gemini".equals(protocol))assertEquals("native-test",body.getString("model"));JSONObject message=new JSONObject();if(turn==0)message.put("tool_calls",new JSONArray().put(new JSONObject().put("id","edit").put("type","function").put("function",new JSONObject().put("name","world_edit").put("arguments",new JSONObject().put("action","replace").put("path",new JSONArray().put("title")).put("source","\"Native API verified\"").toString()))));else message.put("content","Done");JSONObject payload=new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("message",message).put("finish_reason",turn==0?"tool_calls":"stop")));JSONObject edit=new JSONObject().put("action","replace").put("path",new JSONArray().put("title")).put("source","\"Native API verified\"");if("anthropic".equals(protocol))payload=new JSONObject().put("content",new JSONArray().put(turn==0?new JSONObject().put("type","tool_use").put("id","edit").put("name","world_edit").put("input",edit):new JSONObject().put("type","text").put("text","Done")));if("gemini".equals(protocol))payload=new JSONObject().put("candidates",new JSONArray().put(new JSONObject().put("finishReason","STOP").put("content",new JSONObject().put("parts",new JSONArray().put(turn==0?new JSONObject().put("functionCall",new JSONObject().put("id","edit").put("name","world_edit").put("args",edit)).put("thoughtSignature","native-signature"):new JSONObject().put("text","Done"))))));if("openai-responses".equals(protocol))payload=new JSONObject().put("status","completed").put("output",new JSONArray().put(turn==0?new JSONObject().put("type","function_call").put("id","function").put("call_id","edit").put("name","world_edit").put("arguments",edit.toString()):new JSONObject().put("type","message").put("role","assistant").put("content",new JSONArray().put(new JSONObject().put("type","output_text").put("text","Done")))));byte[] response=payload.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);OutputStream out=client.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+response.length+"\r\nConnection: close\r\n\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));out.write(response);out.flush();}}}catch(Throwable e){failure.set(e);}},"provider-contract");responder.start();try{app.startActivity(new Intent(app,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1500);JSONObject settings=(JSONObject)host.store.core.doc("defaultSettings");settings.getJSONArray("profiles").put(new JSONObject().put("id","native-api").put("name","Native API").put("protocol",protocol).put("baseUrl","http://127.0.0.1:"+server.getLocalPort()).put("model","native-test"));settings.getJSONObject("routes").put("building",new JSONObject().put("profileId","native-api").put("model",""));host.request("saveProviderSettings",new JSONObject().put("settings",settings));String source="{\"title\":\"old\",\"exact\":9007199254740993}";String id=host.store.create("Native API test",source).getJSONObject("project").getString("id");host.store.dispatch(id,new JSONObject().put("type","workOrder").put("order",new JSONObject().put("objective","Edit title").put("requirements",new JSONArray()).put("allowedPaths",new JSONArray().put(new JSONArray().put("title")))));host.request("startAgent",new JSONObject().put("id",id).put("kind","work"));JSONObject project=null;long end=System.currentTimeMillis()+45000;while(System.currentTimeMillis()<end){Thread.sleep(300);project=host.store.project(id);if(!java.util.Arrays.asList("PREPARED","RUNNING").contains(project.getJSONArray("tasks").getJSONObject(0).getString("state")))break;}assertNull(String.valueOf(failure.get()),failure.get());assertEquals(project.toString(),"PROPOSAL_READY",project.getJSONArray("tasks").getJSONObject(0).getString("state"));assertEquals(source,project.getString("activeSource"));assertEquals(source.replace("old","Native API verified"),project.getJSONArray("candidates").getJSONObject(0).getString("source"));Thread.sleep(1000);}finally{server.close();responder.join(1000);host.store.setting("providers",original);}}
 @Test public void providerProfilesAndNativeProtocol()throws Exception{String original=host.store.setting("providers");try{JSONObject settings=(JSONObject)host.store.core.doc("defaultSettings");settings.getJSONArray("profiles").put(new JSONObject().put("id","local").put("name","Local").put("protocol","openai").put("baseUrl","http://127.0.0.1:1234/v1").put("model","local-model"));settings.getJSONObject("routes").put("planning",new JSONObject().put("profileId","local").put("model","plan-model"));host.request("saveProviderSettings",new JSONObject().put("settings",settings));JSONObject route=(JSONObject)host.store.core.doc("resolveRoute",host.settings(),"planning");assertEquals("plan-model",route.getString("model"));JSONObject wire=(JSONObject)host.store.core.doc("apiRequest",route,"",new JSONArray().put(new JSONObject().put("role","user").put("text","Hello")),false);assertEquals("http://127.0.0.1:1234/v1/chat/completions",wire.getString("url"));assertFalse(wire.getString("body").contains("world_edit"));Secrets secrets=new Secrets(app);secrets.set("provider-native-test","test-secret");assertEquals("test-secret",new Secrets(app).get("provider-native-test"));secrets.set("provider-native-test","");host.request("featureSet",new JSONObject().put("key","base").put("value","{}"));assertEquals("{}",host.request("featureGet",new JSONObject().put("key","base")));}finally{host.store.setting("providers",original);}}
 @Test public void realAgentStagesProposal()throws Exception{org.junit.Assume.assumeTrue(new File(app.getFilesDir(),"provider/auth.json").isFile());Intent launch=new Intent(app,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);app.startActivity(launch);Thread.sleep(2000);String source="{\"title\":\"old\",\"exact\":9007199254740993}";String id=host.store.create("Android agent smoke",source).getJSONObject("project").getString("id");host.store.dispatch(id,new JSONObject().put("type","workOrder").put("order",new JSONObject().put("objective","Use world_edit to replace path [\"title\"] with JSON string \"Android app verified\". Preserve exact. Then finish.").put("requirements",new JSONArray()).put("allowedPaths",new JSONArray().put(new JSONArray().put("title")))));host.request("startAgent",new JSONObject().put("id",id).put("kind","work"));JSONObject p=null;long end=System.currentTimeMillis()+240000;while(System.currentTimeMillis()<end){Thread.sleep(1000);p=host.store.project(id);String state=p.getJSONArray("tasks").getJSONObject(0).getString("state");if(!state.equals("PREPARED")&&!state.equals("RUNNING"))break;}assertEquals(p.toString(),"PROPOSAL_READY",p.getJSONArray("tasks").getJSONObject(0).getString("state"));assertEquals(source,p.getString("activeSource"));JSONObject candidate=p.getJSONArray("candidates").getJSONObject(0);assertEquals("{\"title\":\"Android app verified\",\"exact\":9007199254740993}",candidate.getString("source"));host.store.dispatch(id,new JSONObject().put("type","accept").put("id",candidate.getString("id")));assertEquals(candidate.getString("source"),host.store.project(id).getString("activeSource"));}
 @Test public void prepareLifecycleTask()throws Exception{org.junit.Assume.assumeTrue("true".equals(InstrumentationRegistry.getArguments().getString("lifecycle")));app.startActivity(new Intent(app,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(2000);String source="{\"title\":\"old\",\"exact\":9007199254740993}";String id=host.store.create("Lifecycle app test",source).getJSONObject("project").getString("id");host.store.dispatch(id,new JSONObject().put("type","workOrder").put("order",new JSONObject().put("objective","First read each of the two fields separately using world_read. Then use world_edit to replace title with JSON string \"Lifecycle verified\". Preserve exact.").put("requirements",new JSONArray()).put("allowedPaths",new JSONArray().put(new JSONArray().put("title")))));java.nio.file.Files.write(new File(app.getFilesDir(),"lifecycle-project.txt").toPath(),id.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
